import{z as i,x as s,o as t,c as d,q as o,j as l,D as E,d as B,s as r,S as A,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"文本作为数据","description":"","frontmatter":{"title":"文本作为数据","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/pm-text-as-data.md","filePath":"econ/pm-text-as-data.md","lastUpdated":1791413859000}'),p={name:"econ/pm-text-as-data.md"};function D(m,a,h,c,u,C){const n=s("Mermaid");return t(),d("div",null,[a[2]||(a[2]=o('<h1 id="文本作为数据" tabindex="-1">文本作为数据 <a class="header-anchor" href="#文本作为数据" aria-label="Permalink to &quot;文本作为数据&quot;">​</a></h1><div class="epigraph"><p>任何进入回归的文本量——情绪分、立场分、不确定指数——都是一次测量决策；测量要验证，验证之后才有资格谈因果。</p><footer>—— 据 Gentzkow, Kelly and Taddy, Text as Data, Journal of Economic Literature 2019 整理</footer></div><p><a href="/econ/pm-dml-deep">上一课</a>把 DML 的得分、交叉拟合与实施清单钉深。缺口换数据形态：经济学的大数据越来越多是文本——财报、新闻稿、电话会纪要、议会与央行发言。Gentzkow–Kelly–Taddy 2019 把「文本作为数据」收成计量问题：文本量是测量，测量要验证，验证之后才能进估计与因果。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>文本的原始形态是高维离散对象——词袋、字符流。任何进入回归的文本量都把高维对象压成一维，这是一次测量决策。三个问题随之而来。测得准不准：分类器的样本外精度，不是样本内拟合。测的东西对不对：通用情绪词典把金融语境里的「负面」词一律记负，10-K 里大量会计术语被误伤——Loughran–McDonald 2011 为金融文本重训词表，换词典即换测量。测量与因果的关系：文本量当结局 \\(y\\)、当回归元 \\(x\\)、当处理的代理，三种用法的要求完全不同，混用是最常见的翻车点。</p><p><span class="marginnote">数字实例：通用情绪词典把「liability（负债）」「depreciation（折旧）」一律记成负面——在财报里它们只是中性的会计术语，一句正常陈述的情绪分就凭空变负。换成 Loughran–McDonald 金融词表后，同一份财报的情绪分会整体移动：换词典不是润色，是换了测量仪器。</span></p><h3 id="三种构造与两个指数" tabindex="-1">三种构造与两个指数 <a class="header-anchor" href="#三种构造与两个指数" aria-label="Permalink to &quot;三种构造与两个指数&quot;">​</a></h3><p>词典法：词表打分，透明可审计，代价是上下文盲。有监督法：Gentzkow–Shapiro 2010 测媒体立场，用「两党共同提案与单党提案」的措辞差异生成训练标签，把立场变成可估计的量——标签的构造本身就是识别设计。生成式与表征法：LDA（Blei–Ng–Jordan 2003）把文档表成主题分布，词向量（Mikolov 等 2013）把词表进连续空间，语义相似变成几何。指数法把前几者组合成可跟踪的时间序列：Baker–Bloom–Davis 2016 的经济政策不确定性指数（EPU）按月扫报并人工核验；Hassan 等 2019 从电话会纪要里量公司层面政治风险，把测量挂钩后续的游说支出与盈余波动做外部效度。</p><p><span class="marginnote">EPU 的构造本身就是验证模板：报纸来源限定、三组检索词（不确定×经济×政策）、按月归一、人工剔除误报条目，再与宏观波动和投资的相关挂外部效度——每一步都可复制、可批评，这与「调出一个模型」的区别正是测量与拟合的区别。</span></p><p><span class="marginnote">直觉类比：词向量把每个词放成空间里的一个点，意思相近的词挨得近——「通胀」与「物价上涨」的距离，比「通胀」与「红豆饼」近得多。语义相似于是变成可计算的几何：距离近算近义，方向一致算情绪同向。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流程按用途分支。文本当 \\(y\\)：先定测量再定识别——政策前后语气变化的评估仍是事件研究与 DiD，测量误差进衰减系数，词典更换要做稳健性。文本当 \\(x\\)：高维文本特征进<a href="/econ/pm-dml-deep">上一课</a>的讨厌函数位次，由正交得分消化其维数；处理之后产生的文本绝不能当控制。文本当处理的代理（谁接触了哪类信息）：测量与分配同时内生，识别设计最重，词典精度救不了。一切用途都要点-in-time：用今天才发布的词表或模型回测历史文本，会把未来信息泄进测量——这与回测里的前视偏差同源。</p>',12)),(t(),l(A,null,{default:E(()=>[r(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%8E%9F%E5%A7%8B%E8%AF%AD%E6%96%99%22%5D%20--%3E%20M%5B%22%E6%9E%84%E9%80%A0%E6%B5%8B%E9%87%8F%3A%20%E8%AF%8D%E5%85%B8%2F%E6%9C%89%E7%9B%91%E7%9D%A3%2F%E4%B8%BB%E9%A2%98%E5%B5%8C%E5%85%A5%22%5D%0A%20%20M%20--%3E%20V%5B%22%E4%B8%89%E9%87%8D%E9%AA%8C%E8%AF%81%3A%20%E6%A0%B7%E6%9C%AC%E5%A4%96%E7%B2%BE%E5%BA%A6%2F%E6%8D%A2%E5%B7%A5%E5%85%B7%2F%E5%A4%96%E9%83%A8%E6%95%88%E5%BA%A6%22%5D%0A%20%20V%20--%3E%20U%7B%22%E7%94%A8%E9%80%94%3F%22%7D%0A%20%20U%20--%3E%7C%22%E5%BD%93%20y%22%7C%20YS%5B%22%E4%BA%8B%E4%BB%B6%E7%A0%94%E7%A9%B6%E4%B8%8E%20DiD%20%E7%85%A7%E6%97%A7%22%5D%0A%20%20U%20--%3E%7C%22%E5%BD%93%20x%22%7C%20XN%5B%22%E8%BF%9B%20DML%20%E7%9A%84%E8%AE%A8%E5%8E%8C%E5%87%BD%E6%95%B0%22%5D%0A%20%20U%20--%3E%7C%22%E5%BD%93%E5%A4%84%E7%90%86%22%7C%20TS%5B%22%E8%AF%86%E5%88%AB%E8%AE%BE%E8%AE%A1%E6%9C%80%E9%87%8D%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[B("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"验证为什么是中心环节：文本量在回归里扮演的角色与其测量性质纠缠——分类器的偏差不是白噪声，是系统性偏移，衰减与放大都朝着错的方向。样本外精度、换工具的稳健性、与外部效度的三重验证，把「编了个指数」变成「有个测量」。金融专用词表的机制同源：同一个词在不同域的效价不同，测量模型的训练分布必须匹配使用分布——通用域词表进金融文本，测的是语言学不是经济学。",-1)),a[5]||(a[5]=e("p",null,"测量偏差按文本量的三种用途各自往哪个方向坏：",-1)),(t(),l(A,null,{default:E(()=>[r(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%96%87%E6%9C%AC%E9%87%8F%E5%B8%A6%E7%B3%BB%E7%BB%9F%E6%80%A7%E5%81%8F%E5%B7%AE%22%5D%20--%3E%20B%5B%22%E5%BD%93%E5%9B%9E%E5%BD%92%E5%85%83%20x%22%5D%0A%20%20A%20--%3E%20C%5B%22%E5%BD%93%E7%BB%93%E5%B1%80%20y%22%5D%0A%20%20A%20--%3E%20D%5B%22%E5%BD%93%E5%A4%84%E7%90%86%E7%9A%84%E4%BB%A3%E7%90%86%22%5D%0A%20%20B%20--%3E%20E%5B%22%E8%A1%B0%E5%87%8F%EF%BC%9A%E6%95%88%E5%BA%94%E8%A2%AB%E6%8B%89%E5%90%91%E9%9B%B6%22%5D%0A%20%20C%20--%3E%20F%5B%22%E5%81%8F%E7%A7%BB%E7%9B%B4%E6%8E%A5%E8%BF%9B%E6%AE%8B%E5%B7%AE%EF%BC%8C%E9%9D%9E%E7%99%BD%E5%99%AA%E5%A3%B0%22%5D%0A%20%20D%20--%3E%20G%5B%22%E5%81%8F%E5%B7%AE%E4%B8%8E%E5%88%86%E9%85%8D%E7%BA%A0%E7%BC%A0%EF%BC%9A%E8%AF%8D%E5%85%B8%E5%86%8D%E5%87%86%E4%B9%9F%E6%95%91%E4%B8%8D%E4%BA%86%E8%AF%86%E5%88%AB%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=o('<p><span class="marginnote">常见误区：用今天训练好的情绪模型回测 2008 年的新闻语料，报出「历史规律」——但 2008 年的决策者手里根本没有这个信号，回测混进了未来信息。文本数据同样要「当时可得的才可用」，与量化回测里不用未来函数是同一条纪律。</span></p><p>不这么做会错在哪：拿样本内分类精度当测量效度；把模型生成的文本量当外生变量；用后来的词表回放历史语料还报告「历史规律」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不教 NLP 工程——分词、预训练与服务化在大模型栏，这里只管测量与推断。大语言模型当标注器是新的测量仪器，误差结构仍在验证纪律之下，且要防「模型间的共同偏置让两套标注互相印证」。语言随年代演化，固定词典会漂移：同一个词在不同年代效价不同，长期面板要按十年段重验。文本嵌入的因果解释——「语义即变量」——默认是误读。测量之后怎么把整条实证线收进规范，是最后一课的事。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>文本进回归前先过测量三问：样本外准不准、测的是不是目标构念、换测量工具结论稳不稳。</li><li>词典透明可审计，有监督靠标签设计，主题与嵌入降维；EPU 与公司政治风险是验证模板。</li><li>用途分三种：当 \\(y\\) 识别设计照旧，当 \\(x\\) 进 DML 的讨厌函数，当处理代理时识别最重。</li><li>点-in-time 是文本数据的硬约束；今天的词典与模型回测昨天会泄漏未来。</li><li>出处：Gentzkow, Kelly and Taddy, <em>JEL</em> 2019；Gentzkow and Shapiro, <em>Econometrica</em> 2010；Loughran and McDonald, <em>JF</em> 2011；Baker, Bloom and Davis, <em>QJE</em> 2016；Hassan, Hollander, van Lent and Tahoun, <em>QJE</em> 2019。</li></ul>',6))])}const T=i(p,[["render",D]]);export{f as __pageData,T as default};
